// Bake `examples/order-flow/workspace` into a module the worker bundle can hold
// in memory.
//
// Generated rather than committed by hand, and generated by the BUILD rather
// than policed by a gate: a browser host serving models that have drifted from
// the ones the VS Code and Theia hosts open would make every cross-host
// comparison meaningless, and the drift would be invisible — both sides parse,
// both sides validate, and only the diagnostics disagree.
//
// Model files only. The workspace's README is prose the language server has no
// extension registered for, so seeding it would add bytes and reach nothing.

import { mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const packageRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const workspaceRoot = resolve(packageRoot, '../workspace');
const outputFile = resolve(packageRoot, 'src/generated/workspace-seed.ts');

const MODEL_EXTENSIONS = ['.domain', '.process', '.layout'];

/** Every model file under `directory`, as paths relative to the workspace root. */
function collectModelFiles(directory) {
   const found = [];
   for (const entry of readdirSync(directory, { withFileTypes: true })) {
      const absolute = join(directory, entry.name);
      if (entry.isDirectory()) {
         found.push(...collectModelFiles(absolute));
      } else if (MODEL_EXTENSIONS.some(extension => entry.name.endsWith(extension))) {
         found.push(absolute);
      }
   }
   return found;
}

const files = collectModelFiles(workspaceRoot).sort();
if (files.length === 0) {
   // A silent empty seed reads downstream as "this workspace has no problems",
   // which is the same shape as a passing run.
   throw new Error(`No model files found under ${workspaceRoot}`);
}

const entries = files
   .map(file => {
      // POSIX separators: these become URI path segments, not filesystem paths,
      // so a Windows build must not bake backslashes into them.
      const relativePath = relative(workspaceRoot, file).split('\\').join('/');
      return `   ${JSON.stringify(relativePath)}: ${JSON.stringify(readFileSync(file, 'utf8'))}`;
   })
   .join(',\n');

const contents = `// GENERATED — do not edit. Run: npm --prefix examples/order-flow/browser run generate
//
// The models from \`examples/order-flow/workspace\`, keyed by workspace-relative
// path, for the in-memory filesystem the browser host seeds itself from.

import type { FileSystemSeed } from '@hydranium/core';

export const ORDER_FLOW_WORKSPACE_SEED: FileSystemSeed = {
${entries}
};
`;

mkdirSync(dirname(outputFile), { recursive: true });
writeFileSync(outputFile, contents);
console.log(`Seeded ${files.length} model files into ${relative(packageRoot, outputFile)}`);
